import 'package:dashcn_cli/src/application/services/locale/locale_tables.dart';

/// Dart code generation for the per-project locale files.
///
/// A faithful port of the kit's `tool/locale.dart` generators, with one
/// copy-mode adaptation: the kit emits
/// `package:dashcn/src/primitives/localizations/localizations.dart` imports
/// (correct for apps depending on the `dashcn` package), while the CLI copies
/// the sources into the app, so every generated file imports the installed
/// copy through [localizationsImport] — a relative path from
/// `dashcn_locales/` to the installed `localizations.dart`, e.g.
/// `../lib/ui/dashcn/primitives/localizations/localizations.dart`.
///
/// Output depends only on the inputs, so re-running is byte-identical and the
/// sync can treat generation as idempotent.

String _memberDart(String key, String signature, String expression) {
  if (signature.isEmpty) {
    return '  @override\n  String get $key => $expression;';
  }
  return '  @override\n  String $key$signature => $expression;';
}

/// The locale file for [code], overriding exactly [keys].
///
/// Keys the project does not need fall back to English through
/// `ComponentLocalizations`.
String generateLocaleFile({
  required LocaleTables tables,
  required String code,
  required Set<String> keys,
  required String localizationsImport,
}) {
  final className = kLocaleClassNames[code];
  if (className == null) {
    throw StateError(
      'locale_tables.json ships "$code" with no generated class name; '
      'extend kLocaleClassNames.',
    );
  }
  tables.checkCode(code);
  final table = tables.resolveTable(code);
  final names = keys.toList()..sort();
  final members = <String>[];
  for (final key in names) {
    final expression = table[key];
    if (expression == null) {
      throw ArgumentError.value(key, 'keys', 'unknown locale key');
    }
    final signature = tables.keys[key]?['signature'] ?? '';
    members.add(_memberDart(key, signature, expression));
  }
  // The number helper and its intl import are emitted only when a key uses
  // them, so no file carries an unused import or an unused private member.
  final usesNumber = members.any((member) => member.contains('_number('));
  final out = StringBuffer();
  out.writeln('// GENERATED by `dashcn` —');
  out.writeln(
    '// do not edit by hand. Re-run `dashcn add` or `dashcn locale` after a registry upgrade.',
  );
  out.writeln();
  out.writeln("import 'package:flutter/widgets.dart';");
  if (usesNumber) {
    out.writeln("import 'package:intl/intl.dart' as intl;");
  }
  out.writeln();
  out.writeln("import '$localizationsImport';");
  out.writeln();
  out.writeln('/// $code strings for this project.');
  out.writeln('///');
  out.writeln(
    '/// Overrides only the keys this project\'s components need; every other',
  );
  out.writeln('/// key falls back to English through ComponentLocalizations.');
  out.writeln('class $className extends ComponentLocalizations {');
  out.writeln('  /// Creates the $code strings.');
  out.writeln('  const $className() : super(${localeConstructor(code)});');
  if (usesNumber) {
    out.writeln();
    out.writeln('  /// Formats [value] as a number in this locale.');
    out.writeln('  String _number(Object? value) {');
    out.writeln("    if (value is! num) return '\$value';");
    out.writeln(
      '    return intl.NumberFormat.decimalPattern(localeName).format(value);',
    );
    out.writeln('  }');
  }
  for (final member in members) {
    out.writeln();
    out.writeln(member);
  }
  out.writeln('}');
  return out.toString();
}

/// The barrel wiring every locale in [codes].
String generateLocaleBarrel({
  required List<String> codes,
  required String localizationsImport,
}) {
  final sorted = codes.toList()..sort();
  final out = StringBuffer();
  out.writeln('// GENERATED by `dashcn` —');
  out.writeln('// do not edit by hand. Re-run `dashcn locale` after a change.');
  out.writeln('//');
  out.writeln('// Import this barrel and spread its members into your app:');
  out.writeln('// ```dart');
  out.writeln('// MaterialApp(');
  out.writeln('//   localizationsDelegates: [');
  out.writeln('//     ...dashcnLocalesDelegates,');
  out.writeln('//     GlobalMaterialLocalizations.delegate,');
  out.writeln('//     GlobalWidgetsLocalizations.delegate,');
  out.writeln('//   ],');
  out.writeln('//   supportedLocales: dashcnSupportedLocales,');
  out.writeln('//   ...');
  out.writeln('// );');
  out.writeln('// ```');
  out.writeln();
  out.writeln(
    "import 'package:flutter/foundation.dart' show SynchronousFuture;",
  );
  out.writeln("import 'package:flutter/widgets.dart';");
  out.writeln();
  out.writeln("import '$localizationsImport';");
  for (final code in sorted) {
    out.writeln("import '${localeFileName(code)}';");
  }
  out.writeln();
  out.writeln('/// Supported locales for every installed locale.');
  out.writeln('final List<Locale> dashcnSupportedLocales = <Locale>[');
  for (final code in sorted) {
    out.writeln('  ${localeConstructor(code)},');
  }
  out.writeln('];');
  out.writeln();
  out.writeln('/// Delegate serving every installed locale.');
  out.writeln(
    'class DashcnLocalesDelegate extends LocalizationsDelegate<ComponentLocalizations> {',
  );
  out.writeln('  /// Creates the delegate.');
  out.writeln('  const DashcnLocalesDelegate();');
  out.writeln();
  out.writeln('  ComponentLocalizations _load(String code) => switch (code) {');
  for (final code in sorted) {
    out.writeln("    '$code' => const ${kLocaleClassNames[code]}(),");
  }
  out.writeln('    _ => ComponentLocalizations.english,');
  out.writeln('  };');
  out.writeln();
  out.writeln('  static String _key(Locale locale) {');
  out.writeln("    if (locale.countryCode == 'BR' &&");
  out.writeln("        locale.languageCode == 'pt') {");
  out.writeln("      return 'pt-BR';");
  out.writeln('    }');
  out.writeln("    if (locale.scriptCode == 'Hans' &&");
  out.writeln("        locale.languageCode == 'zh') {");
  out.writeln("      return 'zh-Hans';");
  out.writeln('    }');
  out.writeln('    return locale.languageCode;');
  out.writeln('  }');
  out.writeln();
  out.writeln('  @override');
  out.writeln('  bool isSupported(Locale locale) => <String>{');
  for (final code in sorted) {
    out.writeln("    '$code',");
  }
  out.writeln('  }.contains(_key(locale));');
  out.writeln();
  out.writeln('  @override');
  out.writeln(
    '  Future<ComponentLocalizations> load(Locale locale) => SynchronousFuture<ComponentLocalizations>(',
  );
  out.writeln('    _load(_key(locale)),');
  out.writeln('  );');
  out.writeln();
  out.writeln('  @override');
  out.writeln('  bool shouldReload(DashcnLocalesDelegate old) => false;');
  out.writeln('}');
  out.writeln();
  out.writeln('/// Delegates covering every installed locale.');
  out.writeln(
    'const List<LocalizationsDelegate<ComponentLocalizations>> dashcnLocalesDelegates =',
  );
  out.writeln('    <LocalizationsDelegate<ComponentLocalizations>>[');
  out.writeln('  DashcnLocalesDelegate(),');
  out.writeln('];');
  return out.toString();
}

/// The slim-install replacement for the kit's `localizations_delegate.dart`.
///
/// A slim install never copies the kit delegate (it imports every per-locale
/// table, none of which are copied); the installed `localizations.dart` still
/// imports and re-exports this path, so the sync writes this English-fallback
/// delegate instead. Apps serve the installed locales through the generated
/// `dashcn_locales` barrel; this file only keeps the installed tree
/// self-consistent for `flutter analyze`.
String generateSlimDelegate() {
  final out = StringBuffer();
  out.writeln('// GENERATED by `dashcn` —');
  out.writeln('// do not edit by hand. Re-run `dashcn add` after a change.');
  out.writeln('//');
  out.writeln(
    '// Slim-install stand-in for the kit delegate: the per-locale tables live',
  );
  out.writeln(
    '// in `dashcn_locales/` (served by its barrel), so this delegate only',
  );
  out.writeln('// guarantees the English fallback.');
  out.writeln();
  out.writeln(
    "import 'package:flutter/foundation.dart' show SynchronousFuture;",
  );
  out.writeln("import 'package:flutter/widgets.dart';");
  out.writeln();
  out.writeln("import 'localizations.dart';");
  out.writeln();
  out.writeln('/// Loads the English [ComponentLocalizations] fallback.');
  out.writeln('class ComponentLocalizationsDelegate');
  out.writeln(
    '    extends LocalizationsDelegate<ComponentLocalizations> {',
  );
  out.writeln('  /// Creates the delegate.');
  out.writeln('  const ComponentLocalizationsDelegate();');
  out.writeln();
  out.writeln('  @override');
  out.writeln(
    '  bool isSupported(Locale locale) => locale.languageCode == \'en\';',
  );
  out.writeln();
  out.writeln('  @override');
  out.writeln(
    '  Future<ComponentLocalizations> load(Locale locale) => SynchronousFuture<ComponentLocalizations>(',
  );
  out.writeln('    ComponentLocalizations.english,');
  out.writeln('  );');
  out.writeln();
  out.writeln('  @override');
  out.writeln(
      '  bool shouldReload(ComponentLocalizationsDelegate old) => false;');
  out.writeln('}');
  out.writeln();
  out.writeln('/// Returns the English [ComponentLocalizations] fallback.');
  out.writeln('ComponentLocalizations lookupComponentLocalizations(');
  out.writeln('  Locale locale,');
  out.writeln(') =>');
  out.writeln('    ComponentLocalizations.english;');
  return out.toString();
}
